# Let's test different corner patches to identify the target class and trigger pattern
# Patch is 3-5 pixels wide, placed 1 pixel in from one corner
# Patch types: white square, checkerboard, or random black/white noise

def make_patch(patch_type='white', size=4):
    """Create a patch of given type and size (square)."""
    if patch_type == 'white':
        return torch.ones(3, size, size)  # White patch (1.0 in normalized space = ~255/255)
    elif patch_type == 'black':
        return torch.zeros(3, size, size)
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, size, size)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
        return patch
    elif patch_type == 'noise':
        return torch.randint(0, 2, (3, size, size)).float()
    else:
        raise ValueError(f"Unknown patch type: {patch_type}")

def apply_patch(images, patch, corner='tl'):
    """Apply patch to images at specified corner (1 pixel in from edge)."""
    # images: (N, 3, 32, 32) uint8
    # patch: (3, h, w) float [0,1]
    # corner: 'tl', 'tr', 'bl', 'br'

    patched = images.clone().float() / 255.0
    h, w = patch.shape[1], patch.shape[2]

    if corner == 'tl':  # top-left
        patched[:, :, 1:1+h, 1:1+w] = patch
    elif corner == 'tr':  # top-right
        patched[:, :, 1:1+h, 32-w-1:32-1] = patch
    elif corner == 'bl':  # bottom-left
        patched[:, :, 32-h-1:32-1, 1:1+w] = patch
    elif corner == 'br':  # bottom-right
        patched[:, :, 32-h-1:32-1, 32-w-1:32-1] = patch

    # Convert back to uint8
    return (patched * 255).clamp(0, 255).to(torch.uint8)

